package com.jinloes.practice;
import java.util.Arrays; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: vote strings in a bracketed list, for example: [ABC, ACB, ABC, ACB, ACB]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(Solution.rankTeams(new String[]{"ABC","ACB","ABC","ACB","ACB"})).isEqualTo("ACB"); assertThat(Solution.rankTeams(new String[]{"WXYZ","XYZW"})).isEqualTo("XWYZ"); assertThat(Solution.rankTeams(new String[0])).isEmpty(); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ System.out.println(Solution.rankTeams(parse(input))); }catch(RuntimeException e){ System.out.println(USAGE); } } static String[] parse(String input){ String c=input.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new String[0]; return Arrays.stream(c.split("\\s+")).toArray(String[]::new); } }
